   "name": "OcenaPodania.dmn",
   "content": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<definitions xmlns=\"https://www.omg.org/spec/DMN/20191111/MODEL/\" xmlns:dmndi=\"https://www.omg.org/spec/DMN/20191111/DMNDI/\" xmlns:dc=\"http://www.omg.org/spec/DMN/20180521/DC/\" xmlns:modeler=\"http://camunda.org/schema/modeler/1.0\" id=\"Definitions_1soqz33\" name=\"DRD\" namespace=\"http://camunda.org/schema/1.0/dmn\" exporter=\"Camunda Modeler\" exporterVersion=\"5.39.0\" modeler:executionPlatform=\"Camunda Cloud\" modeler:executionPlatformVersion=\"8.7.0\">\n  <decision id=\"ocena-podania\" name=\"Ocena Podania\">\n    <decisionTable id=\"DecisionTable_1yq413z\">\n      <input id=\"Input_1\" label=\"Punkty ECTS\">\n        <inputExpression id=\"InputExpression_1\" typeRef=\"number\">\n          <text>podanie.punktyECTS</text>\n        </inputExpression>\n      </input>\n      <input id=\"InputClause_0llx2ez\" label=\"Uzasadnienie podania\">\n        <inputExpression id=\"LiteralExpression_1bdi6p0\" typeRef=\"number\">\n          <text>string length(podanie.uzasadnienie)</text>\n        </inputExpression>\n      </input>\n      <output id=\"Output_1\" label=\"Czy pozytywna? \" name=\"czyPozytywna\" typeRef=\"boolean\" />\n      <output id=\"OutputClause_1vtt8ls\" label=\"Uzasadnienie decyzji\" name=\"uzasadnienie\" typeRef=\"string\" />\n      <rule id=\"DecisionRule_10du5v1\">\n        <inputEntry id=\"UnaryTests_09blo7o\">\n          <text>&gt;= 18</text>\n        </inputEntry>\n        <inputEntry id=\"UnaryTests_02aivpb\">\n          <text></text>\n        </inputEntry>\n        <outputEntry id=\"LiteralExpression_03f42k9\">\n          <text>true</text>\n        </outputEntry>\n        <outputEntry id=\"LiteralExpression_0v6k7bt\">\n          <text>\"Wystarczająco dużo punktów ECTS\"</text>\n        </outputEntry>\n      </rule>\n      <rule id=\"DecisionRule_0z6qlus\">\n        <inputEntry id=\"UnaryTests_11ppw5k\">\n          <text>&lt; 15</text>\n        </inputEntry>\n        <inputEntry id=\"UnaryTests_1of09qs\">\n          <text></text>\n        </inputEntry>\n        <outputEntry id=\"LiteralExpression_0hpo115\">\n          <text>false</text>\n        </outputEntry>\n        <outputEntry id=\"LiteralExpression_1hzi67j\">\n          <text>\"Za mało punktów ECTS\"</text>\n        </outputEntry>\n      </rule>\n      <rule id=\"DecisionRule_1d4wyzc\">\n        <inputEntry id=\"UnaryTests_0vihuyz\">\n          <text>[15..18[</text>\n        </inputEntry>\n        <inputEntry id=\"UnaryTests_1heurf8\">\n          <text>&gt;= 10</text>\n        </inputEntry>\n        <outputEntry id=\"LiteralExpression_0z9rf5t\">\n          <text>true</text>\n        </outputEntry>\n        <outputEntry id=\"LiteralExpression_1hh2p8d\">\n          <text>\"Mało punktów ECTS ale dobre uzasadnienie\"</text>\n        </outputEntry>\n      </rule>\n      <rule id=\"DecisionRule_09zfeti\">\n        <inputEntry id=\"UnaryTests_11ivvl0\">\n          <text>[15..18[</text>\n        </inputEntry>\n        <inputEntry id=\"UnaryTests_1wtnvca\">\n          <text>&lt; 10</text>\n        </inputEntry>\n        <outputEntry id=\"LiteralExpression_0gc7nwl\">\n          <text>null</text>\n        </outputEntry>\n        <outputEntry id=\"LiteralExpression_0axeoe7\">\n          <text>\"Za słabe uzasadnienie, brak decyzji\"</text>\n        </outputEntry>\n      </rule>\n    </decisionTable>\n  </decision>\n  <dmndi:DMNDI>\n    <dmndi:DMNDiagram>\n      <dmndi:DMNShape dmnElementRef=\"ocena-podania\">\n        <dc:Bounds height=\"80\" width=\"180\" x=\"160\" y=\"100\" />\n      </dmndi:DMNShape>\n    </dmndi:DMNDiagram>\n  </dmndi:DMNDI>\n</definitions>\n"
